"""Component 4429 of layers.15.mlp.down_proj: a diffuse, context-driven neuron of layer 15.

Its activation is mostly the MLP hidden unit 4429 (its input direction is about half that
unit), so it is heavy-tailed: most positions sit near 0, and a few percent reach 5 to 25.
What this program does: a weak, token-type offset. Opening and closing brackets, digits,
operators and separators (the punctuation and numerals of code and maths) sit a little
above zero; ordinary lowercase words sit near zero; the first token of a document is zero.
A token that already occurred earlier in the same document gets a small push up.

This is a deliberately simple approximation. The real activation depends on context that no
token-level rule captures, so this program explains almost none of its variance.
"""
import re

CLASS_VALUE = {
    "open": 0.30,
    "close": 0.40,
    "digit": 0.16,
    "op": 0.15,
    "sep": 0.11,
    "quote": 0.14,
    "newline": 0.10,
    "other": 0.07,
    "word": 0.07,
    "lower": 0.04,
}
SEEN_BONUS = 0.08


def token_class(s):
    if re.fullmatch(r"\s*\d", s):
        return "digit"
    if re.fullmatch(r"\s*[\(\[\{]", s):
        return "open"
    if re.fullmatch(r"\s*[\)\]\}]", s):
        return "close"
    if re.fullmatch(r"\s*[=+\-*/<>&|%^!~]+", s):
        return "op"
    if re.fullmatch(r"\s*[.,;:]", s):
        return "sep"
    if re.fullmatch(r"\s*[\'\"`]", s):
        return "quote"
    if "\n" in s:
        return "newline"
    if re.fullmatch(r"\s*[a-z]+", s):
        return "lower"
    if re.fullmatch(r"\s*[A-Za-z_]+", s):
        return "word"
    return "other"


READS = ()


def step(carry, prefix, upstream):
    """carry: the tokens seen so far in the current document (a set), or None at a row start."""
    t = prefix.position
    doc = prefix.document_ids[t]
    if carry is None or t == 0 or prefix.document_ids[t - 1] != doc:
        carry = set()
    token = prefix.token_ids[-1]
    if t == 0 or prefix.document_ids[t - 1] != doc:
        value = 0.0
    else:
        value = CLASS_VALUE[token_class(prefix.token_strings[-1])]
        if token in carry:
            value += SEEN_BONUS
    carry.add(token)
    return carry, float(value)

"""Layer 15 MLP hidden unit 4443 (the down_proj component), explained as word triggers.

The unit is sparse and spiky: most tokens sit near -0.05, while a scattered set of
words fire it strongly. The triggers, grouped by theme, with typical activations:

- the chat role name "assistant" (the token after <|im_start|>): about 9;
- COVID-19 vocabulary ("COVID", "coronavirus", "pandemic", "SARS", "lockdown"): about 8;
  a digit within 200 tokens after one of these words (as in "COVID-19", "SARS-CoV-2"): about 2.3;
- code words "async", "await", and the "(f" of print(f"..."): about 6 to 9;
- developer-tool names ("conda", "pytest", "github", "npm", "git", "workspace", ...): about 3;
- public figures and social media names ("Trump", "Biden", "Instagram", "Twitter"): about 4.

Every other token gets the resting value. The program tracks the position of the last
COVID word in the current document (carried between steps), and resets at document
boundaries, as the model does.
"""

READS = ()

REST = -0.05
COVID = {"COVID", "Covid", "covid", "SARS", "pandemic", "Pandemic", "coronavirus", "Coronavirus", "lockdown"}
CODE = {"async": 9.0, "await": 9.0, "(f": 6.0}
TOOLS = {"conda", "tqdm", "pytest", "github", "npm", "git", "cargo", "yarn", "bash", "jest", "pandas", "numpy", "torch", "workspace"}
PEOPLE = {"Trump", "Biden", "Obama", "Instagram", "Twitter", "Facebook", "YouTube"}
COVID_WINDOW = 200


def step(carry, prefix, upstream):
    t = prefix.position
    word = prefix.token_strings[-1].strip()
    doc = prefix.document_ids[-1]
    last_covid, cur_doc = carry if carry is not None else (-10**9, doc)
    if doc != cur_doc:
        last_covid = -10**9
    if word in COVID:
        last_covid = t
    if word == "assistant":
        value = 9.0
    elif word in COVID:
        value = 8.0
    elif word in CODE:
        value = CODE[word]
    elif word in TOOLS:
        value = 3.0
    elif word in PEOPLE:
        value = 4.0
    elif word.isdigit() and t - last_covid <= COVID_WINDOW:
        value = 2.3
    else:
        value = REST
    return (last_covid, doc), value

"""Layer 15, MLP neuron 4444 (the down_proj component), read as a main-clause detector.

The component is almost entirely one hidden unit of the layer-15 MLP. It is negative where
a main clause begins after an opening subordinate clause, as in "If you want it, [you] need
to pay", "When the soldier felt that..., [he] said", "The more you ask, [the] better", and
on the first word of an if-body in code ("if (x) [return]"). The comma that closes such an
opener is negative too: strongly after a clause ("If ...,") and less after a phrase ("In 1797,").
Subjects and auxiliaries of ordinary main clauses are mildly negative; everything else is near 0.
"""
from collections.abc import Mapping

READS = ()

CLAUSE_OPENERS = {"if", "when", "after", "as", "since", "once", "because", "although", "though",
                  "while", "unless", "whenever", "having", "before", "until"}
PHRASE_OPENERS = {"in", "for", "to", "from", "on", "at", "of", "during", "with", "given", "despite",
                  "by", "about", "through", "between", "within", "without", "upon", "into", "under",
                  "over", "among", "across", "regarding", "according", "based", "unlike", "except"}
SUBJECT_PRONOUNS = {"he", "she", "we", "they", "i", "you", "it", "then", "there", "this"}
DETERMINERS = {"the", "a", "an"}
AUXILIARIES = {"is", "are", "was", "were", "be", "can", "will", "would", "should", "may", "must",
               "might", "could", "shall", "has", "have", "had", "do", "does", "did"}
CODE_JUMPS = {"return"}
BOUNDARIES = {".", "!", "?", ";", "{", "}"}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if prefix.position > 0 else ""
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        carry = {"first": None, "commas": 0, "since": None}
    first, commas, since = carry["first"], carry["commas"], carry["since"]
    value = 0.0
    if since == 0:  # the first word after an opener's comma: the main clause's subject
        if tok in SUBJECT_PRONOUNS:
            value = -8.0
        elif tok in DETERMINERS:
            value = -4.0
        else:
            value = -2.0
    elif since == 1:
        value = -4.5 if tok in AUXILIARIES else -1.5
    elif tok in CODE_JUMPS:
        value = -4.7
    elif tok in SUBJECT_PRONOUNS and prev == ",":
        value = -5.5
    elif tok in DETERMINERS and prev == ",":
        value = -3.0
    elif tok in SUBJECT_PRONOUNS:
        value = -1.0
    elif tok in AUXILIARIES and prev in SUBJECT_PRONOUNS:
        value = -1.3
    elif tok == ",":
        if commas == 0 and first in CLAUSE_OPENERS:
            value = -5.0
        elif commas == 0 and first in PHRASE_OPENERS:
            value = -2.5
        else:
            value = -0.4
    # update the sentence state; whitespace-only tokens do not start a sentence
    if tok in BOUNDARIES or "\n" in prefix.token_strings[-1]:
        carry = {"first": None, "commas": 0, "since": None}
    elif tok:
        if since is not None:
            since += 1
        if first is None:
            first = tok.lower()
        if tok == ",":
            commas += 1
            if first in CLAUSE_OPENERS and since is None:
                since = 0
        carry = {"first": first, "commas": commas, "since": since}
    else:
        carry = {"first": first, "commas": commas, "since": since}
    return carry, value

"""Layer 15, MLP hidden unit 4456 (the down_proj component 4456), as a readable feature.

What it does: this unit is quiet on most tokens and switches on where the text is about to
run or print something. It is strongest on
  - the word that starts a shell command or a print / log / assert call (`cat`, `grep`,
    `git`, `print`, `console.log`, `assert`, ...), and the phrase "Current working directory";
  - the `me` / `'s` of "Let me" / "Let's" / "Here's", which opens an action;
  - a flag right after a shell command name ("grep -", "cat -n");
  - shell chaining punctuation (`&&`, `|`, `>&`) a little less.
Its output direction promotes words such as "check", "inspect", "test", so it reads as
"time to look at or verify something".

The program predicts the activation from the current and previous token only. The bulk of
the activation (std about 0.6, mostly noise-like and not predicted by token identity or by
lexical context) is not modelled, so this explains only a few percent of its variance.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

# Words that start a shell command, or a print / log / assert call, in code or agent transcripts.
COMMAND_WORDS = {
    "print", "println", "Println", "printf", "Printf", "fmt", "log", ".log", ".println",
    ".Printf", "console", "echo", "puts", "cout", "cat", "tail", "head", "grep", "git",
    "bash", "cd", "ls", "npm", "python", "node", "diff", "tee", "wc", "pip", "cargo",
    "assert", "assertEquals", "assertNull", "assertNotNull", "expect", "test", "check",
    "inspect", "verify",
}
# Words of the phrase "Current working directory", as a command's output header.
CWD_WORDS = {"Current", "working", "directory"}
# Shell chaining and redirection.
CHAIN = {"&&", "|", ">&", ">>", "2>&1"}
# Words that, after "Let" / "Here", open an action: "Let me ...", "Let's ...", "Here's ...".
OPENERS = {"Let", "let", "Here"}
# Command names after which a flag such as "-" or "--" is typical ("grep -", "cat -n").
SHELL_NAMES = {"grep", "cat", "git", "ls", "tail", "head", "rm", "find", "python", "npm", "node"}


def step(carry, prefix, upstream: Mapping):
    cur = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if cur in COMMAND_WORDS:
        value = 1.3
    elif cur in CWD_WORDS:
        value = 2.0
    elif cur in {"me", "'s"} and prev in OPENERS:
        value = 2.1
    elif cur in {"-", "--"} and prev in SHELL_NAMES:
        value = 6.6
    elif cur in CHAIN:
        value = 0.5
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP hidden unit 4458 (this component's activation), read as a register detector.

The component is, almost entirely, one hidden unit of the layer-15 MLP's down projection.
It goes negative on conversational, emotional speech and positive on formal or technical
writing:

- strongly negative on interjections and reactions ("Wait", "Hmm", "Oh", "Wow", "sorry",
  "guys", "god"), and on sentence-final particles and question words of spoken Chinese or
  Japanese (吗 呢 啊 ね よ 怎么 为什么);
- moderately negative on question and exclamation marks, and on feeling or evaluative
  words ("really", "amazing", "please", "love");
- a little negative on first and second person pronouns;
- slightly positive on formal and technical vocabulary ("perhaps", "carefully", "print").

It also keeps a fading memory of those scores within a document, because the sign tends
to persist over a few tokens of the same conversation. The memory resets at each document
boundary.

This explains only about 2 to 3 percent of the activation's variance. The activation is
diffuse: most of its variance sits on ordinary words, where the context decides the sign
and no word list reaches it.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

INTERJECTIONS = {
    "oh", "hmm", "hm", "wait", "wow", "whoa", "ah", "ugh", "oops", "omg", "hi", "hello",
    "thanks", "thank", "sorry", "god", "guys", "dude", "yay", "okay", "ooh",
}
CJK_PARTICLES = {"吗", "呢", "啊", "吧", "嘛", "ね", "よ", "か", "怎么", "为什么", "什么", "何", "谁"}
EMOTIVE = {
    "awesome", "amazing", "wonderful", "crazy", "great", "lovely", "delicious", "please",
    "love", "hate", "funny", "really", "so", "too", "such", "glad", "cool", "nice",
    "fantastic", "incredible", "strange", "confused",
}
PRONOUNS = {"i", "me", "my", "you", "your"}
FORMAL = {"perhaps", "basically", "carefully", "mostly", "regularly", "despite", "except"}
TECHNICAL = {"print", "printf", "include", "directory", "sizeof"}
QUESTION_MARKS = {"?", "？"}
EXCLAMATION_MARKS = {"!", "！"}

MEMORY_DECAY = 0.5  # the share of the memory kept from one token to the next
MEMORY_WEIGHT = 0.6


def token_score(text: str) -> float:
    """How conversational or emotional a token is: negative means more so, positive formal."""
    word = text.strip().lower()
    if word in INTERJECTIONS:
        return -2.8
    if word in CJK_PARTICLES:
        return -1.0
    if word in QUESTION_MARKS:
        return -1.2
    if word in EXCLAMATION_MARKS:
        return -1.0
    if word in EMOTIVE:
        return -0.5
    if word in PRONOUNS:
        return -0.2
    if word in FORMAL or word in TECHNICAL:
        return 0.5
    return 0.0


def step(carry, prefix, upstream: Mapping):
    """The activation here: this token's register score plus the fading memory before it."""
    doc = prefix.document_ids[-1]
    memory, last_doc = carry if carry is not None else (0.0, None)
    if doc != last_doc:
        memory = 0.0
    score = token_score(prefix.token_strings[-1])
    value = score + MEMORY_WEIGHT * memory
    memory = MEMORY_DECAY * memory + (1 - MEMORY_DECAY) * score
    return (memory, doc), float(value)

"""Layer 15, MLP neuron 4466 (this component reads essentially that one hidden unit).

What it does, in plain terms. The neuron is a "looking into it" versus "here is the outcome"
detector. It is positive on verbs of inquiry and testing (investigated, examined, tested,
tried, asked, searched, analyzed, checked, look), and a bit more positive right after a verb
of intent or asking (asked *if*, tried *to*). It is negative on words that report an outcome
(result, found, revealed, showed, surprisingly, interestingly).

Inside an agent's tool transcript it is strongly negative on the markup that opens a tool's
output: the newline right after <tool_response>, the "OBSERVATION:" heading, the line break that
closes a tool call's JSON or a header line, and the newline after <|im_end|>.

The numbers are least-squares fits on 20k training positions. Most of the neuron's variance
is diffuse and is not captured: this program explains only about 5% of it.
"""

READS = ()

TOOL_TAGS = {"<tool_call>", "</tool_call>", "<tool_response>"}
OBSERVATION_PIECES = {"O", "BS", "ERV", "ATION"}
INQUIRY_WORDS = {
    "investigate", "investigated", "investigates", "investigating", "examine", "examined",
    "examines", "examining", "explore", "explored", "try", "tried", "tries", "trying", "test",
    "tested", "testing", "attempt", "attempted", "search", "searched", "seek", "sought",
    "evaluate", "evaluated", "analyze", "analyzed", "analysed", "study", "studied", "assess",
    "assessed", "check", "checked", "ask", "asked", "asks", "question", "questioned", "aim",
    "aimed", "discuss", "discussed", "compare", "compared", "measure", "measured", "look",
    "looked", "looking", "grep", "cat", "verify", "verified", "inquire",
}
FINDING_WORDS = {
    "result", "results", "resulted", "resulting", "yield", "yielded", "yields", "reveal",
    "revealed", "reveals", "show", "showed", "shows", "found", "find", "finds", "discover",
    "discovered", "notice", "noticed", "surprise", "surprised", "surprising", "surprisingly",
    "interestingly", "fortunately", "luckily", "sadly", "apparently", "demonstrate",
    "demonstrated", "observe", "observed",
}
INTENT_WORDS = {"asked", "tried", "attempted", "decided", "trying", "tries", "wanted", "want", "told", "asks", "ask"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    in_tool = carry[1] if carry is not None and carry[0] == doc else False
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word, prev_word = token.strip(), before.strip()
    if token in TOOL_TAGS:
        in_tool = True
    value = 0.0
    if before == "<tool_response>":
        value += -5.4
    if in_tool:
        if token.strip() in OBSERVATION_PIECES or before.strip() in OBSERVATION_PIECES:
            value += -1.9
        if token.endswith(":\n") or token.endswith("}}\n"):
            value += -3.2
        elif token.endswith("\n"):
            value += -0.35
        if before == "<|im_end|>":
            value += -2.8
    word, prev_word = word.lower(), prev_word.lower()
    if word in FINDING_WORDS:
        value += -0.5
    if word in INQUIRY_WORDS:
        value += 0.35
    if prev_word in INTENT_WORDS:
        value += 0.95
    return (doc, in_tool), value

"""Equals signs in algebra, and escaped or broken line breaks in running prose.

Most of this component's activation variance sits on a few tokens:

- A relation sign (=, =-, ≠, ≤, ≥, <, >) right after a variable letter, as in
  "x =", "a² =", "b =", in algebra: strongly positive. It is much larger when the
  last few tokens hold an implication arrow (⇒, =>, ==>), as in a worked derivation
  that rearranges an equation. A sign after a digit or a closing bracket is mildly
  positive, and any other sign is about zero.
- A backslash-n written as " \\" right after a word, as in escaped prose
  ("does not think\\nthat"): negative. A plain line break after a word is mildly
  negative.

Everything else predicts zero. Only the current token and the same document's
recent tokens are read, so the program is causal and resets at document borders.
"""
import re

READS = ()

RELATIONS = {"=", "=-", "≠", "≤", "≥", "<", ">", ")="}
ARROWS = {"⇒", "=>", "==>", "⟹"}
LINE_BREAKS = {"\n", "\n\n", "\r\n", " \r\n"}
VARIABLE = re.compile(r"[a-zA-Z]{1,2}|[a-zA-Z]?[²³]|[α-ωΑ-Ω]")
WORD_END = re.compile(r"[A-Za-z]$")


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    tok = raw.strip()
    doc = prefix.document_ids[-1]
    # The up to 8 tokens before this one, in the same document.
    before = [
        s.strip()
        for s, d in zip(prefix.token_strings[-9:-1], prefix.document_ids[-9:-1])
        if d == doc
    ]
    prev = before[-1] if before else ""
    arrow = any(s in ARROWS or s.endswith("=>") for s in before)
    if tok in RELATIONS:
        if VARIABLE.fullmatch(prev):
            return carry, (21.0 if arrow else 3.3)
        if prev[-1:] and prev[-1] in ")0123456789":
            return carry, (7.0 if arrow else 1.1)
        return carry, (4.0 if arrow else 0.2)
    if raw == " \\":
        return carry, (-4.7 if WORD_END.search(prev) else -0.2)
    if raw in LINE_BREAKS and WORD_END.search(prev):
        return carry, -0.6
    return carry, 0.0
